mapper.select:
select 
from api_automation_spec
where project_id = #{projectId}
  and spec_digest = #{specDigest}
  and status != 'ARCHIVED'
limit 1

select project_id
from api_automation_spec
where id = #{id}

select project_id
from api_automation_generation_task
where id = #{id}

select project_id
from api_automation_script_bundle
where id = #{id}

select project_id
from api_automation_run
where id = #{id}

mapper.insert:
insert into api_automation_endpoint_snapshot (
    id, spec_id, project_id, service_name, operation_id, http_method, path, summary, tags,
    parameter_count, request_body_present, response_statuses, schema_digest, diff_status,
    asset_api_id, diff_summary_json, last_diff_at, synced_at, sync_error_summary, created_at, updated_at
) values (
    #{id}, #{specId}, #{projectId}, #{serviceName}, #{operationId}, #{httpMethod}, #{path}, #{summary}, #{tags},
    #{parameterCount}, #{requestBodyPresent}, #{responseStatuses}, #{schemaDigest}, #{diffStatus},
    #{assetApiId}, cast(coalesce(#{diffSummaryJson}, '{}') as jsonb), #{lastDiffAt}, #{syncedAt}, #{syncErrorSummary},
    #{createdAt}, #{updatedAt}
)

insert into api_automation_run (
    id, project_id, bundle_id, environment_id, base_url_digest, base_url_host, status,
    timeout_seconds, case_count, trace_id, runner_mode, error_code, error_summary,
    created_by, updated_by, started_at, completed_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{bundleId}, #{environmentId}, #{baseUrlDigest}, #{baseUrlHost}, #{status},
    #{timeoutSeconds}, #{caseCount}, #{traceId}, #{runnerMode}, #{errorCode}, #{errorSummary},
    #{createdBy}, #{updatedBy}, #{startedAt}, #{completedAt}, #{createdAt}, #{updatedAt}
)

insert into api_automation_run_result (
    id, run_id, case_id, status, duration_ms, assertion_summary_json,
    error_code, error_summary, created_at, updated_at
) values (
    #{id}, #{runId}, #{caseId}, #{status}, #{durationMs},
    cast(coalesce(#{assertionSummaryJson}, '{}') as jsonb),
    #{errorCode}, #{errorSummary}, #{createdAt}, #{updatedAt}
)

